use vstd::prelude::*;

verus! {

/// Returns a new vector formed by inserting `delim` between consecutive
/// elements of `numbers`, with no trailing delimiter.
fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        // Length property: empty stays empty; otherwise 2n-1.
        res@.len() == if numbers@.len() == 0 { 0 } else { 2 * numbers@.len() - 1 },

        // Even indices are original elements in order.
        forall|k: int|
            0 <= k < numbers@.len() ==>
                res@[2*k] == numbers@[k],

        // Odd indices are the delimiter (only those that exist).
        forall|k: int|
            0 <= k < numbers@.len() - 1 ==>
                res@[2*k + 1] == delim,

        // No trailing delimiter after the last input element (implied by above,
        // but stated explicitly).
        numbers@.len() > 0 ==> res@[res@.len() - 1] == numbers@[numbers@.len() - 1],
{
    let n = numbers.len();
    let mut res: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            res@.len() == if i == 0 { 0 } else { 2 * (i as int) - 1 },
            forall|k: int| 0 <= k < i as int ==> res@[2*k] == numbers@[k],
            forall|k: int| 0 <= k < i as int - 1 ==> res@[2*k + 1] == delim,
            i > 0 ==> res@[res@.len() - 1] == numbers@[(i as int) - 1],
    {
        res.push(numbers[i]);
        if i + 1 < n {
            res.push(delim);
        }
        i += 1;
    }

    res
}

} // verus!